    };

    private string _fullName = "", _phone = "", _email = "", _address = "", _notes = "";
    private string _payment = "COD";
    private string? _error;
    private bool _busy, _prefilled;

    protected override void OnInitialized() => Cart.Changed += OnChanged;
    private void OnChanged() => _ = InvokeAsync(StateHasChanged);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;
        await Cart.EnsureLoadedAsync();
        await PrefillAsync();
        StateHasChanged();
    }

    // Điền sẵn thông tin khách hàng đã đăng nhập
    private async Task PrefillAsync()
    {
        if (_prefilled) return;
        _prefilled = true;
        var accountId = await GetAccountIdAsync();
        if (accountId == null) return;

        await using var db = await DbFactory.CreateDbContextAsync();
        var c = await db.Customers.FirstOrDefaultAsync(x => x.AccountId == accountId);
        if (c == null) return;
        _fullName = c.FullName;
        _phone = c.PhoneNumber;
        _email = c.Email ?? "";
        _address = c.Address;
    }

    private async Task<int?> GetAccountIdAsync()
    {
        var state = await AuthProvider.GetAuthenticationStateAsync();
        var claim = state.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
        return int.TryParse(claim, out var id) ? id : null;
    }

    private async Task PlaceOrder()
    {
        _error = null;
        var items = Cart.GetCart().ToList();
        if (items.Count == 0) return;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _error = "Vui lòng nhập đầy đủ thông tin người nhận!";
            return;
        }

        _busy = true;
        try
        {
            await using var db = await DbFactory.CreateDbContextAsync();

            Customer? customer = null;
            var accountId = await GetAccountIdAsync();
            if (accountId != null)
                customer = await db.Customers.FirstOrDefaultAsync(c => c.AccountId == accountId);

            if (customer == null)
            {
                customer = new Customer
                {
                    FullName = _fullName.Trim(),
                    PhoneNumber = _phone.Trim(),
                    Email = string.IsNullOrWhiteSpace(_email) ? null : _email.Trim(),
                    Address = _address.Trim(),
                    CreatedAt = DateTime.Now
                };
                db.Customers.Add(customer);
                await db.SaveChangesAsync();
            }

            var order = new Order
            {
                CustomerId = customer.Id,
                OrderDate = DateTime.Now,
                TotalAmount = items.Sum(i => i.TotalPrice),
                OrderStatus = "Pending",
                PaymentMethod = _payment,
                ShippingAddress = _address.Trim(),
                Notes = string.IsNullOrWhiteSpace(_notes) ? null : _notes.Trim()
            };
            db.Orders.Add(order);
            await db.SaveChangesAsync();

            foreach (var item in items)
            {
                db.OrderDetails.Add(new OrderDetail
                {
                    OrderId = order.Id,
                    ProductId = item.ProductId,
                    Quantity = item.Quantity,
                    UnitPrice = item.Price,
                    TotalPrice = item.TotalPrice
                });
                var product = await db.Products.FindAsync(item.ProductId);
                if (product != null) product.Quantity = Math.Max(0, product.Quantity - item.Quantity);
            }
            await db.SaveChangesAsync();

            await Cart.ClearCartAsync();
            Nav.NavigateTo($"/order-success/{order.Id}");
        }
        catch (Exception ex)
        {
            _error = "Không thể đặt hàng: " + ex.Message;
        }
        finally
        {
            _busy = false;
        }
    }

    public void Dispose() => Cart.Changed -= OnChanged;

